Here is the commit message:
drm/xe/queue: Call fini on exec queue creation fail

Every call to queue init should have a corresponding fini call.
Skipping this would mean skipping removal of the queue from GuC list
(which is part of guc_id allocation). A damaged queue stored in
exec_queue_lookup list would lead to invalid memory reference,
sooner or later.

Call fini to free guc_id. This must be done before any internal
LRCs are freed.

Since the finalization with this extra call became very similar to
__xe_exec_queue_fini(), reuse that. To make this reuse possible,
alter xe_lrc_put() so it can survive NULL parameters, like other
similar functions.

v2: Reuse _xe_exec_queue_fini(). Make xe_lrc_put() aware of NULLs.

Fixes: 3c1fa4aa60b1 ("drm/xe: Move queue init before LRC creation")
Signed-off-by: Tomasz Lis <tomasz.lis@intel.com>
Reviewed-by: Matthew Brost <matthew.brost@intel.com> (v1)
Signed-off-by: Michal Wajdeczko <michal.wajdeczko@intel.com>
Link: https://patch.msgid.link/20260226212701.2937065-2-tomasz.lis@intel.com
(cherry picked from commit 393e5fea6f7d7054abc2c3d97a4cfe8306cd6079)
Signed-off-by: Rodrigo Vivi <rodrigo.vivi@intel.com>

Here is the root cause:
In __xe_exec_queue_init, on failure after queue init (which includes GuC ID allocation), the error path (err_lrc) only freed LRCs but did not call __xe_exec_queue_fini to release the GuC ID and remove the queue from the exec_queue_lookup list. This left a stale entry leading to invalid memory references.

Here is the patch:

+static void __xe_exec_queue_fini(struct xe_exec_queue *q)
+{
+	int i;
+
+	q->ops->fini(q);
+
+	for (i = 0; i < q->width; ++i)
+		xe_lrc_put(q->lrc[i]);
+}
+
 static int __xe_exec_queue_init(struct xe_exec_queue *q, u32 exec_queue_flags)
 {
 	int i, err;
 	u32 flags = 0;

 	/*
 	 * PXP workloads executing on RCS or CCS must run in isolation (i.e. no
 	 * other workload can use the EUs at the same time). On MTL this is done
 	 * by setting the RUNALONE bit in the LRC, while starting on Xe2 there
 	 * is a dedicated bit for it.
 	 */
 	if (xe_exec_queue_uses_pxp(q) &&
 	    (q->class == XE_ENGINE_CLASS_RENDER || q->class == XE_ENGINE_CLASS_COMPUTE)) {
 		if (GRAPHICS_VER(gt_to_xe(q->gt)) >= 20)
 			flags |= XE_LRC_CREATE_PXP;
 		else
 			flags |= XE_LRC_CREATE_RUNALONE;
 	}

 	if (!(exec_queue_flags & EXEC_QUEUE_FLAG_KERNEL))
 		flags |= XE_LRC_CREATE_USER_CTX;

 	err = q->ops->init(q);
 	if (err)
 		return err;

 	/*
 	 * This must occur after q->ops->init to avoid race conditions during VF
 	 * post-migration recovery, as the fixups for the LRC GGTT addresses
 	 * depend on the queue being present in the backend tracking structure.
 	 *
 	 * In addition to above, we must wait on inflight GGTT changes to avoid
 	 * writing out stale values here. Such wait provides a solid solution
 	 * (without a race) only if the function can detect migration instantly
 	 * from the moment vCPU resumes execution.
 	 */
 	for (i = 0; i < q->width; ++i) {
 		struct xe_lrc *lrc;

 		xe_gt_sriov_vf_wait_valid_ggtt(q->gt);
 		lrc = xe_lrc_create(q->hwe, q->vm, q->replay_state,
 				    xe_lrc_ring_size(), q->msix_vec, flags);
 		if (IS_ERR(lrc)) {
 			err = PTR_ERR(lrc);
 			goto err_lrc;
 		}

 		/* Pairs with READ_ONCE to xe_exec_queue_contexts_hwsp_rebase */
 		WRITE_ONCE(q->lrc[i], lrc);
 	}

 	return 0;

 err_lrc:
-	for (i = i - 1; i >= 0; --i)
-		xe_lrc_put(q->lrc[i]);
+	__xe_exec_queue_fini(q);
 	return err;
 }

-static void __xe_exec_queue_fini(struct xe_exec_queue *q)
-{
-	int i;
-
-	q->ops->fini(q);
-
-	for (i = 0; i < q->width; ++i)
-		xe_lrc_put(q->lrc[i]);
-}
-
 struct xe_exec_queue *xe_exec_queue_create(struct xe_device *xe, struct xe_vm *vm,
 					   u32 logical_mask, u16 width,
 					   struct xe_hw_engine *hwe, u32 flags,
 					   u64 extensions)
 {
 	struct xe_exec_queue *q;
 	int err;

 	/* VMs for GSCCS queues (and only those) must have the XE_VM_FLAG_GSC flag */
 	xe_assert(xe, !vm || (!!(vm->flags & XE_VM_FLAG_GSC) == !!(hwe->engine_id == XE_HW_ENGINE_GSCCS0)));

 	q = __xe_exec_queue_alloc(xe, vm, logical_mask, width, hwe, flags,
 				  extensions);
 	if (IS_ERR(q))
 		return q;

 	err = __xe_exec_queue_init(q, flags);
 	if (err)
 		goto err_post_alloc;

 	/*
 	 * We can only add the queue to the PXP list after the init is complete,
 	 * because the PXP termination can call exec_queue_kill and that will
 	 * go bad if the queue is only half-initialized. This means that we
 	 * can't do it when we handle the PXP extension in __xe_exec_queue_alloc
 	 * and we need to do it here instead.
 	 */
 	if (xe_exec_queue_uses_pxp(q)) {
 		err = xe_pxp_exec_queue_add(xe->pxp, q);
 		if (err)
 			goto err_post_init;
 	}

 	return q;

 err_post_init:
 	__xe_exec_queue_fini(q);
 err_post_alloc:
 	__xe_exec_queue_free(q);
 	return ERR_PTR(err);
 }
 ALLOW_ERROR_INJECTION(xe_exec_queue_create, ERRNO);


